from pathlib import Path
import re,json
p=Path('chapters/E00/E00_c.html');s=p.read_text()
def before_pareto(key,body):
 global s
 start=s.index('id="'+key+'"');i=s.index('<button class="pareto-btn',start);s=s[:i]+body+s[i:]
def ref(*ids):return '<span class="src">'+', '.join('<button class="w" data-k="e00-sources-2026">['+i+']</button>' for i in ids)+'</span>'
before_pareto('e00-s-anat','''<div class="key"><b>Science → clinique.</b> Localiser une anomalie neurologique, auditive ou de croissance aide à décrire le retentissement ; aucun de ces territoires ne prouve isolément la cause iodée. <b>Science → examen.</b> L’échographie situe la glande et mesure son volume ; elle ne remplace pas le couple fT4–TSH. <b>Science → traitement.</b> Une recherche étiologique par imagerie ne retarde pas la substitution d’un nouveau-né hypothyroïdien confirmé. <b>À retenir.</b> Structure de la glande, fonction hormonale et séquelles du développement sont trois observations distinctes.</div>'''+ref('S102','S106','S108','S109'))
s=s.replace('Le cerveau dépend de l’iode de la mère avant 18-20 semaines, puis de la thyroïde de l’enfant.','Au début de la grossesse, le fœtus dépend largement de la thyroxine maternelle. La contribution fœtale augmente ensuite, tandis que la contribution maternelle persiste : il ne s’agit pas d’un basculement exclusif à une date fixe.')
s=s.replace('18-20 semaines : thyroïde fœtale fonctionnelle','18–20 semaines : maturation fonctionnelle fœtale')
s=s.replace('la dépendance fœtale à la thyroxine maternelle jusqu’à 18-20 semaines','la contribution maternelle majeure avant la maturation fœtale vers 18–20 semaines, puis la coexistence des contributions maternelle et fœtale')
before_pareto('e00-s-physio','''<p><b>Le rétrocontrôle comme outil de lecture.</b> Une baisse de thyroxine produite par la glande tend à augmenter la stimulation par la thyrotropine. Ce raisonnement suppose un axe de commande fonctionnel. Dans l’hypothyroïdie centrale, une TSH non élevée peut être inadaptée à une fT4 basse : la valeur de TSH, prise seule, donne alors une fausse impression de normalité. La décision s’appuie sur les deux dosages, l’âge et le contexte clinique.</p><div class="key"><b>Science → clinique.</b> La disponibilité hormonale au cours du développement explique l’urgence néonatale et l’intérêt d’une prévention avant la grossesse. <b>Science → examen.</b> Le rétrocontrôle explique pourquoi on interprète conjointement fT4 et TSH. <b>Science → traitement.</b> Le traitement apporte l’hormone déficitaire ; la surveillance vérifie l’équilibre sans confondre rythme de correction de la fT4 et de la TSH. <b>À retenir.</b> Un apport iodé adéquat et une substitution hormonale répondent à des besoins différents.</div>'''+ref('S102','S106','S114'))
before_pareto('e00-s-bioch','''<p><b>Du transport à la libération.</b> La captation d’iodure ne suffit pas à produire une hormone : l’iode doit être incorporé aux résidus tyrosine de la thyroglobuline, puis les résidus iodés sont couplés. La thyroperoxydase participe à l’organification et au couplage. Les hormones restent d’abord liées au support protéique de la colloïde ; la reprise et la dégradation de ce support permettent ensuite leur libération. Il faut donc distinguer substrat disponible, machinerie de synthèse et hormone circulante.</p><p>Cette distinction explique les diagnostics différentiels. Une anomalie du transporteur SLC5A5, de TPO ou de la thyroglobuline peut provoquer une hypothyroïdie congénitale malgré des apports iodés suffisants. Le consensus décrit ces défauts de synthèse dans le cadre des dyshormonogenèses. Ils ne deviennent pas des syndromes de carence iodée E00 du seul fait qu’ils touchent une étape utilisant l’iode. La génétique est ciblée sur le phénotype et une utilité clinique attendue, et non demandée automatiquement devant toute TSH élevée.</p><div class="key"><b>Science → clinique.</b> Carence de substrat et défaut de synthèse peuvent aboutir au même déficit hormonal. <b>Science → examen.</b> La biologie confirme la fonction ; imagerie et investigation génétique ciblée précisent certaines causes. <b>Science → traitement.</b> Ajouter de l’iode n’est pas une réponse universelle : l’excès iodé peut lui-même perturber la fonction, notamment chez le prématuré. <b>À retenir.</b> Identifier une hormone basse ne suffit pas à identifier l’étape biochimique en cause.</div>'''+ref('S102','S106'))
s=s.replace('Le médecin de premier recours ne diagnostique pas le crétinisme, il identifie la femme enceinte à risque d’apport insuffisant et l’oriente vers une multivitamine contenant de l’iode.','Le médecin de premier recours évalue les apports et les facteurs de risque, recherche les signes qui justifient une exploration clinique et discute avec la femme enceinte d’un complément selon les conseils suisses. Il ne diagnostique pas un syndrome congénital à partir de la seule iodurie d’un groupe.')
chart='''<figure><svg role="img" aria-label="Médianes d’iodurie suisses : 127 microgrammes par litre chez les enfants d’âge scolaire, 97 chez les femmes enceintes ; seuils de suffisance de groupe respectifs 100 et150." viewBox="0 0 660 230" style="width:100%;height:auto;background:#fff;color:#17364b;border-radius:12px"><text x="20" y="26" fill="#17364b" font-size="17">Enquête suisse 2020–2022 — médianes d’iodurie (µg/L)</text><text x="20" y="64" fill="#17364b" font-size="15">Enfants, n = 362</text><rect x="225" y="45" width="254" height="26" fill="#247382"/><text x="490" y="64" fill="#17364b" font-size="16">127</text><line x1="425" y1="38" x2="425" y2="80" stroke="#782b30" stroke-width="3"/><text x="295" y="100" fill="#782b30" font-size="13">Seuil de suffisance du groupe : 100</text><text x="20" y="141" fill="#17364b" font-size="15">Grossesse, n = 473</text><rect x="225" y="122" width="194" height="26" fill="#247382"/><text x="429" y="141" fill="#17364b" font-size="16">97</text><line x1="525" y1="115" x2="525" y2="157" stroke="#782b30" stroke-width="3"/><text x="295" y="177" fill="#782b30" font-size="13">Seuil de suffisance du groupe : 150</text><text x="20" y="212" fill="#17364b" font-size="14">Échelle commune : 2 pixels par µg/L ; aucune valeur individuelle représentée.</text></svg><figcaption>Comparaison didactique des médianes non ajustées publiées dans l’étude suisse et présentées par l’OSAV, avec les bornes inférieures de suffisance de l’OMS pour chaque groupe. Les effectifs sont ceux des échantillons urinaires. Le graphique ne représente ni une distribution, ni une incidence d’E00, ni l’effet causal d’un supplément ; il ne fournit pas de diagnostic individuel. Construction graphique à partir des valeurs lues, sans image anatomique générée.</figcaption></figure>'''
before_pareto('e00-s-sante',chart+'''<p><b>Ce que le programme mesure.</b> Les prélèvements de l’enquête suisse ont été recueillis en2020–2022. La médiane brute de97µg/L chez les femmes enceintes ne doit pas être remplacée par la médiane ajustée de l’étude sans signaler le changement de méthode. Les résultats d’un sous-groupe supplémenté dépendent également de la source et de la définition : la page OSAV présente88 contre140µg/L, alors que l’article principal donne81 contre129µg/L. Le cours conserve les valeurs globales communes et ne fusionne pas ces sous-groupes.</p><p>Dans le guide OMS2007, la fréquence des TSH sur sang total buvard supérieures à5mUI/L constitue un indicateur de population lorsque les prélèvements sont faits à trois–quatre jours avec une méthode suffisamment sensible : une fréquence inférieure à3% soutient une suffisance iodée. Ce seuil n’est ni le seuil sérique de traitement ni un seuil de rappel affirmé pour le programme suisse. Les antiseptiques iodés peuvent augmenter la TSH néonatale et compliquer l’interprétation.</p><div class="key"><b>Science → clinique.</b> L’insuffisance des apports d’un groupe justifie une prévention adaptée, sans attribuer le diagnostic à chacun de ses membres. <b>Science → examen.</b> L’iodurie et la TSH néonatale de surveillance ont des populations, méthodes et limites différentes. <b>Science → traitement.</b> En Suisse, choisir le sel iodé sans augmenter le sel ; discuter individuellement le complément pendant le projet de grossesse, la grossesse et l’allaitement. <b>À retenir.</b> Indicateur collectif, examen diagnostique et dose de médicament sont trois objets distincts.</div>'''+ref('S103','S104','S111','S112','S114'))
flow='''<figure><svg role="img" aria-label="Démarche sémiologique : décrire la trajectoire du développement et mesurer la fonction hormonale actuelle, puis rechercher une cause compatible sans conclure sur la géographie ou l’iodurie seules." viewBox="0 0 660 220" style="width:100%;height:auto;background:#fff;border-radius:12px"><rect x="15" y="15" width="300" height="75" rx="8" fill="#e3eff3"/><rect x="345" y="15" width="300" height="75" rx="8" fill="#e3eff3"/><text x="30" y="44" fill="#17364b" font-size="17">Trajectoire du développement</text><text x="30" y="70" fill="#17364b" font-size="14">Croissance, audition, motricité</text><text x="360" y="44" fill="#17364b" font-size="17">Fonction hormonale actuelle</text><text x="360" y="70" fill="#17364b" font-size="14">fT4 + TSH, âge, terme, méthode</text><path d="M165 90 L165 115 L330 115 L330 135 M495 90 L495 115 L330 115" stroke="#247382" fill="none" stroke-width="3"/><rect x="110" y="135" width="440" height="68" rx="8" fill="#17364b"/><text x="132" y="161" fill="white" font-size="17">Confronter l’histoire, la clinique et la cause</text><text x="132" y="187" fill="white" font-size="14">Ni la géographie ni l’iodurie seules ne concluent</text></svg><figcaption>Deux dimensions complémentaires du raisonnement : conséquences anciennes du développement et déficit hormonal actuel. Schéma logique original fondé sur le consensus et les séries historiques ; ce n’est ni une image anatomique ni un score validé. La prise en charge d’un déficit néonatal confirmé n’attend pas la fin de l’enquête étiologique.</figcaption></figure>'''
s=s.replace('<section class="ilot" id="e00-semio-signs"',flow+'<section class="ilot" id="e00-semio-signs"')
s=s.replace('presque tous les personnes atteintes','presque toutes les personnes atteintes')
p.write_text(s)
